"""Create a local visual report; benchmark photos never enter production assets."""
import base64,io,json
from pathlib import Path
from PIL import Image
from collect import ROOT,OUT
from ablate import expand,references
manifest=json.loads((OUT/'manifest.json').read_text())
summary=json.loads((OUT/'summary.json').read_text())
ablations=json.loads((OUT/'ablations.json').read_text())
refs=references()
labels={'baseline':'Original pipeline','zero_cost_early_stop':'Safe rotation shortcut','no_vitl':'Remove ViT-L','no_fenify':'Remove Fenify','v4_only':'Only V4 + constraints','v4_raw':'Only V4, no constraints','no_chess_constraints':'Remove chess constraints','no_detector_identity':'Remove detector identity','uniform_weights':'Use equal model weights','best_model_only':'Use just the best geometry model','no_alignment_search':'Remove frame alignment','fenify_single_view':'Only one Fenify rotation','v4_single_view':'Only one V4 rotation','both_single_view':'One rotation per model','no_inventory_penalty':'Remove inventory penalty','no_occupancy_lock':'Remove occupancy lock','single_decoder_orientation':'Only one pawn-axis orientation'}
pieces={c:base64.b64encode((ROOT/'web/pieces'/f"{'w' if c.isupper() else 'b'}{c.upper()}.svg").read_bytes()).decode() for c in 'PNBRQKpnbrqk'}
cases=[]
for case in manifest[:7]:
    ident=case['id'];im=Image.open(case['path']).convert('RGB');im.thumbnail((700,550));buf=io.BytesIO();im.save(buf,'JPEG',quality=82)
    base=json.loads((OUT/(ident+'.json')).read_text())['baseline']
    records={r['variant']:r for r in ablations if r['id']==ident}
    candidate=json.loads((OUT/'step2.json').read_text()) if (OUT/'step2.json').exists() else []
    final=next((r for r in candidate if r['id']==ident),None)
    cases.append({'id':ident,'image':base64.b64encode(buf.getvalue()).decode(),'reference':refs[ident],'baseline':base['placement'],'records':records,'passes':len(final['passes']) if final else None})
validation={}
for name in ('step1','step2'):
    file=OUT/(name+'.json')
    if file.exists():
        rows=json.loads(file.read_text());validation[name]={'boards':len(rows),'identical':sum(not r['differences'] for r in rows),'passes':sum(len(r['passes']) for r in rows),'old_passes':9*len(rows)}
payload=json.dumps({'cases':cases,'pieces':pieces,'labels':labels,'summary':summary,'validation':validation}).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scanner simplification — measured removals</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f1eb;color:#202a27;font:16px/1.55 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:40px 24px}h1{font-size:38px;line-height:1.15;max-width:850px;margin:8px 0 20px}h2{font-size:24px}p{max-width:850px}.eyebrow{color:#547267;font-size:12px;letter-spacing:2px;text-transform:uppercase}.metrics{display:flex;gap:16px;flex-wrap:wrap}.metric{background:#e1e9e2;border-radius:10px;padding:16px 24px}.metric strong{font-size:28px;display:block}section{margin:32px 0}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;padding:10px 14px;border-bottom:1px solid #ddd}th{font-size:13px;color:#52675d}td:nth-child(n+2),th:nth-child(n+2){text-align:right}.scroll{overflow:auto}.safe{background:#e1efdf}.bad{color:#aa302b}.muted{color:#59635e;font-size:14px}select{font:inherit;padding:10px;border:1px solid #9aa59d;border-radius:6px;background:white;max-width:100%}.sticky{position:sticky;top:0;background:#f4f1ebee;padding:12px 0;z-index:2;backdrop-filter:blur(8px)}.case{background:white;padding:24px;border-radius:12px;margin:24px 0}.grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}.photo{width:100%;max-height:360px;object-fit:contain;background:#ecebe6}.board{display:grid;grid-template-columns:repeat(8,1fr);aspect-ratio:1;border:3px solid #263d34;max-width:360px}.sq{position:relative;display:grid;place-items:center;background:#e8d7b9;min-width:0}.sq.dark{background:#769281}.sq img{width:88%;height:88%}.sq.changed{box-shadow:inset 0 0 0 3px #e5a119}.sq.wrong:after{content:"";position:absolute;right:3px;top:3px;background:#ce3831;border:1px solid white;width:8px;height:8px;border-radius:50%}.sq small{position:absolute;bottom:0;left:2px;font-size:9px;line-height:1;color:#243b31}.caption{font-size:13px;margin:8px 0}.legend span{display:inline-block;margin-right:16px}.dot{color:#ce3831}.change-list{font-size:14px;word-break:break-word}footer{font-size:13px;color:#66716a} @media(max-width:850px){.grid{grid-template-columns:1fr 1fr}.grid>div:first-child{grid-column:1/-1}.photo{max-height:300px}}@media(max-width:500px){main{padding:24px 12px}h1{font-size:29px}.case{padding:14px}.grid{gap:12px}.sq small{font-size:7px}}
</style><main><div class="eyebrow">Chess scanner · simplification audit · 2 October 2026</div><h1>Remove work that cannot change the answer.</h1><p>Whole-layer removals produced new errors. The retained simplifications skip unused fallback models, discard no-longer-needed image warping, and stop rotation searches only at their proven minimum score. The output comparison includes every response field except elapsed time.</p><div class="metrics" id="metrics"></div><section><h2>Which removals were safe?</h2><p class="muted">Single-factor tests on 43 boards. “New errors” were correct in the baseline but become wrong; fixes elsewhere do not cancel them. Four user photos have partial labels, so these are confirmed errors, not complete accuracy estimates.</p><div class="scroll"><table><thead><tr><th>Change tested</th><th>Identical boards</th><th>New errors</th><th>Fixed errors</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><h2>Inspect the actual board changes</h2><div class="sticky"><select id="variant" aria-label="Choose a pipeline removal"></select><p class="legend muted"><span style="color:#a56b00">Gold outline: changed square</span><span><b class="dot">●</b> Confirmed wrong square</span></p></div><div id="cases"></div></section><footer>Parity preserves existing mistakes too. Reserved validation positions are distinct from the previous 36 CVChess positions, but training overlap with CVChess is unknown. No benchmark labels or photo identifiers are used by the production recognizer. Exact piece identities remain uncertain on portions of four diagnostic photos; hover a square to see the reference allowance.</footer></main><script>const D=PAYLOAD;
const metric=(n,t)=>`<div class="metric"><strong>${n}</strong>${t}</div>`;
let final=D.validation.step2;document.querySelector('#metrics').innerHTML=final?metric(final.identical+'/'+final.boards,'identical full responses')+metric(final.passes+' / '+final.old_passes,'neural passes after / before')+metric('0','new errors from retained cuts'):metric('43 / 43','cached rotation-shortcut parity');
document.querySelector('#rows').innerHTML=D.summary.filter(x=>x.variant!=='baseline').map(x=>`<tr class="${x.new_errors===0&&x.changed_squares===0?'safe':''}"><td>${D.labels[x.variant]}</td><td>${x.identical_boards}/43</td><td class="${x.new_errors?'bad':''}">${x.new_errors}</td><td>${x.fixed_errors}</td></tr>`).join('');
const select=document.querySelector('#variant');select.innerHTML=Object.entries(D.labels).filter(([k])=>k!=='baseline').map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
function expand(fen){return [...fen].flatMap(c=>c==='/'?[]:/[1-8]/.test(c)?Array(+c).fill('.'):c)}
function board(fen,reference,changes=[]){return '<div class="board">'+expand(fen).map((c,i)=>{let square='abcdefgh'[i%8]+(8-Math.floor(i/8));let allowed=reference[i];return `<div title="${square}: ${c}; reference: ${allowed}" class="sq ${(Math.floor(i/8)+i%8)%2?'dark':''} ${changes.includes(i)?'changed':''} ${allowed.includes(c)?'':'wrong'}">${c==='.'?'':`<img alt="${c}" src="data:image/svg+xml;base64,${D.pieces[c]}">`}<small>${square}</small></div>`}).join('')+'</div>'}
function render(){document.querySelector('#cases').innerHTML=D.cases.map(c=>{let r=c.records[select.value],b=c.records.baseline,changed=r.changed_squares.map(i=>'abcdefgh'[i%8]+(8-Math.floor(i/8)));return `<article class="case"><h3>Photo ${c.id.replace('photo','')}</h3><div class="grid"><div><img alt="Original chess photo ${c.id}" class="photo" src="data:image/jpeg;base64,${c.image}"><p class="caption">Kept simplification: ${c.passes??'—'} neural passes (previously 9)</p></div><div>${board(c.baseline,c.reference)}<p class="caption">Original pipeline · ${b.wrong.length} confirmed errors</p></div><div>${board(r.placement,c.reference,r.changed_squares)}<p class="caption">${D.labels[select.value]} · ${r.wrong.length} confirmed errors</p></div></div><p class="change-list">${changed.length?'Changed '+changed.length+' squares: '+changed.join(', '):'Identical placement: all 64 squares match.'} New errors: ${r.new_errors.length}; fixed errors: ${r.fixed_errors.length}.</p></article>`}).join('')};select.onchange=render;render();</script></html>'''.replace('PAYLOAD',payload)
folder=OUT/'review';folder.mkdir(exist_ok=True);(folder/'index.html').write_text(page)
print(folder/'index.html')
